<script setup>
import {ref,computed,onMounted,nextTick} from 'vue';import {useRouter} from 'vue-router';
import {AURICWELL_MARK_URL} from '../../constants/auricwellBrand';
import api from '../../services/api';import {useAuthStore} from '../../store/auth';import FamilyPortalShell from '../../components/portal/FamilyPortalShell.vue';
const router=useRouter(),auth=useAuthStore();const profile=ref(null),choice=ref(''),panel=ref('home'),loading=ref(true),error=ref(''),appointments=ref([]),plan=ref(null),documents=ref(null),conversation=ref(null),messages=ref([]),draft=ref(''),sending=ref(false);let generation=0;
const choices=computed(()=>(profile.value?.agencies||[]).flatMap(a=>a.services.map(s=>({...s,agency:a,key:`${a.id}:${s.id}`}))));
const selected=computed(()=>choices.value.find(c=>c.key===choice.value));const params=computed(()=>({agencyId:selected.value?.agency.id,serviceId:selected.value?.id}));
const nav=[{key:'home',label:'My dashboard',icon:'dashboard'},{key:'appointments',label:'My appointments',icon:'appointments'},{key:'plan',label:'My plan',icon:'treatment'},{key:'documents',label:'My documents',icon:'documents'},{key:'messages',label:'Secure messages',icon:'messages'},{key:'security',label:'Account security',icon:'settings'},{key:'logout',label:'Sign out',icon:'account'}];
const visibleAppointments=computed(()=>panel.value==='home'?appointments.value.filter(a=>new Date(a.startAt)>=new Date()).slice(0,3):appointments.value);
const title=computed(()=>nav.find(n=>n.key===panel.value)?.label||'My portal');
const when=a=>new Intl.DateTimeFormat('en-US',{dateStyle:'medium',timeStyle:'short',timeZone:a.timeZone||'America/Denver'}).format(new Date(a.startAt));
async function navigate(key){if(key==='logout'){await auth.logout('manual');return;}if(key==='security'){await router.push('/account-security');return;}panel.value=key;await loadSection();await nextTick();document.getElementById('family-portal-content')?.scrollIntoView({block:'start'});}
async function loadSection(){const run=++generation;loading.value=true;error.value='';conversation.value=null;messages.value=[];draft.value='';try{
 if(!selected.value)return;
 const options={params:params.value,skipGlobalLoading:true};
 if(['home','appointments'].includes(panel.value)){const r=await api.get('/dependent-portal/appointments',options);if(run===generation)appointments.value=r.data.appointments;}
 if(panel.value==='plan'){const r=await api.get('/dependent-portal/plan',options);if(run===generation)plan.value=r.data;}
 if(panel.value==='documents'){const r=await api.get('/dependent-portal/documents',options);if(run===generation)documents.value=r.data;}
 if(panel.value==='messages'){const r=await api.post('/dependent-portal/conversation',params.value);if(run!==generation)return;conversation.value=r.data;await refreshMessages(run);}
 }catch(e){if(run===generation)error.value=e.response?.data?.error?.message||'Could not open this section. Please try again.';}finally{if(run===generation)loading.value=false;}}
async function refreshMessages(run=generation){if(!conversation.value)return;const r=await api.get(`/dependent-portal/messages/${conversation.value.threadId}`,{skipGlobalLoading:true});if(run===generation)messages.value=r.data;}
async function send(){if(sending.value||!draft.value.trim())return;const run=generation,id=conversation.value.threadId;sending.value=true;try{await api.post(`/dependent-portal/messages/${id}`,{body:draft.value});if(run===generation){draft.value='';await refreshMessages(run);}}catch(e){if(run===generation)error.value=e.response?.data?.error?.message||'Your message could not be sent.';}finally{sending.value=false;}}
async function download(file){try{const r=await api.get(`/dependent-portal/documents/${file.id}`,{params:params.value,responseType:'blob'});const url=URL.createObjectURL(r.data),a=document.createElement('a');a.href=url;a.download=file.title;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch{error.value='This document is no longer available. Please refresh.';}}
onMounted(async()=>{try{profile.value=(await api.get('/dependent-portal/me')).data;choice.value=choices.value[0]?.key||'';await loadSection();}catch(e){error.value=e.response?.data?.error?.message||'Your personal portal could not be opened.';loading.value=false;}});
</script>
<template><FamilyPortalShell :brand-name="selected?.kind==='tutoring'?selected?.agency.name:'AuricWell'" brand-subtitle="My personal portal" :logo-url="selected?.kind==='tutoring'?selected?.agency.logo:AURICWELL_MARK_URL" :agency-name="selected?.kind==='tutoring'?'':selected?.agency.name" :title="title" :user-name="profile?.name" :navigation="nav" :active="panel" account-key="security" @navigate="navigate"><template #context><label class="own-service" v-if="choices.length>1">My service<select v-model="choice" @change="loadSection"><option v-for="c in choices" :key="c.key" :value="c.key">{{c.agency.name}} · {{c.label}} · {{c.providerName}}</option></select></label></template>
<p v-if="loading" role="status">Opening your portal…</p><p v-if="error" class="error" role="alert">{{error}} <button @click="loadSection">Try again</button></p>
<template v-if="!loading&&profile"><section v-if="panel==='home'" class="personal-card"><h2>Welcome, {{profile.name.split(' ')[0]}}</h2><p>Your appointments, progress, and conversations in one place.</p><p v-if="selected?.providerName"><strong>{{selected.kind==='tutoring'?'Your tutor':'Your provider'}}:</strong> {{selected.providerName}}</p><p v-if="profile.schoolName">{{profile.schoolName}}</p><div class="quick"><button @click="navigate('messages')">Message {{selected?.providerName||'my team'}}</button><button @click="navigate('plan')">View my plan</button></div></section>
<section v-if="['home','appointments'].includes(panel)" class="personal-card"><h2>{{panel==='home'?'My upcoming appointments':'My appointments'}}</h2><p v-if="!visibleAppointments.length">No appointments are listed yet.</p><article v-for="a in visibleAppointments" :key="a.id" class="appointment"><strong>{{when(a)}}</strong><p>{{a.providerName}} · {{a.modality==='IN_PERSON'?'In person':'Virtual'}} · {{a.status.replaceAll('_',' ')}}</p><a v-if="a.joinUrl" :href="a.joinUrl">Join session →</a></article></section>
<section v-if="panel==='plan'" class="personal-card"><h2>{{profile.name.split(' ')[0]}}’s plan</h2><p v-if="plan?.sharingPending">Your care team hasn’t shared a plan with your personal login yet.</p><p v-else-if="!plan?.hasActivePlan">Your plan will appear here when it is ready.</p><template v-else><h3>{{plan.plan?.title}}</h3><article v-for="(g,i) in plan.goals" :key="g.id" class="goal"><h3>Goal {{i+1}}: {{g.goalText}}</h3><p v-for="(o,j) in g.objectives" :key="o.id"><strong>Objective {{j+1}}:</strong> {{o.objectiveText}}</p></article></template></section>
<section v-if="panel==='documents'" class="personal-card"><h2>Shared with me</h2><p v-if="!documents?.files?.length">Documents your team shares directly with you will appear here.</p><button v-for="f in documents?.files||[]" :key="f.id" class="document" @click="download(f)">{{f.title}} · Download</button></section>
<section v-if="panel==='messages'&&conversation" class="personal-card"><h2>Message {{conversation.providerName}}</h2><p class="audience">{{conversation.audience}}</p><button @click="refreshMessages()">Refresh messages</button><p v-if="!messages.length">Start your conversation below.</p><article v-for="m in messages" :key="m.id" class="message"><strong>{{Number(m.sender_user_id)===Number(auth.user?.id)?'You':conversation.providerName}}</strong><p>{{m.body}}</p></article><form @submit.prevent="send"><label>Your message<textarea v-model="draft" maxlength="4000" rows="4" required /></label><button :disabled="sending||!draft.trim()">{{sending?'Sending…':'Send secure message'}}</button></form></section></template></FamilyPortalShell></template>
<style scoped>.personal-card{padding:24px;background:white;border:1px solid #d4e0eb;border-radius:16px;margin:0 0 20px;color:#193653}.personal-card p{line-height:1.6}.own-service{display:grid;gap:5px;margin-top:12px;max-width:550px;font-size:13px}.own-service select,textarea{padding:12px;border:1px solid #bacddd;border-radius:8px;font:inherit;width:100%;box-sizing:border-box}.quick{display:flex;gap:12px;flex-wrap:wrap}button,.appointment a{font:inherit;padding:10px 14px;border:1px solid #285f91;border-radius:8px;background:#285f91;color:#fff;cursor:pointer}.appointment,.goal{padding:18px 0;border-top:1px solid #e1e8ef}.appointment a{display:inline-block;text-decoration:none}.message{padding:14px;background:#f1f6fb;border-radius:12px;margin:12px 0;white-space:pre-wrap}.audience{padding:12px;background:#edf6f2;border-radius:8px}.personal-card form label{display:grid;gap:8px;margin:14px 0}.document{display:block;margin:12px 0}.error{color:#a12222}button:disabled{opacity:.6}</style>
